import{_ as e,o as a,c as n,ak as d}from"./chunks/framework.DJ-92fJv.js";const g=JSON.parse('{"title":"⚙️ 进程管理","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/process-manager.md","filePath":"features/process-manager.md"}'),r={name:"features/process-manager.md"};function s(l,t,i,o,c,h){return a(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="⚙️-进程管理" tabindex="-1">⚙️ 进程管理 <a class="header-anchor" href="#⚙️-进程管理" aria-label="Permalink to “⚙️ 进程管理”">​</a></h1><p><strong>主菜单选项：<code>7</code></strong></p><p>进程管理提供了对学生端相关进程的细粒度控制，包括单个终止、批量终止和持续监控模式。</p><h2 id="可管理的进程" tabindex="-1">可管理的进程 <a class="header-anchor" href="#可管理的进程" aria-label="Permalink to “可管理的进程”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">编号</th><th>进程名</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><code>MultiClient.exe</code></td><td>学生端主进程</td></tr><tr><td style="text-align:center;">2</td><td><code>ScreenRender.exe</code></td><td>屏幕广播进程</td></tr><tr><td style="text-align:center;">3</td><td><code>ScreenRender_Y.exe</code></td><td>屏幕广播辅助进程</td></tr><tr><td style="text-align:center;">4</td><td><code>DeviceControl_x64.exe</code></td><td>设备控制进程</td></tr><tr><td style="text-align:center;">5</td><td><code>BlackSlient.exe</code></td><td>黑屏安静进程</td></tr><tr><td style="text-align:center;">6</td><td><code>Student.exe</code></td><td>学生端主程序</td></tr><tr><td style="text-align:center;">7</td><td><code>OEProtect.exe</code></td><td>保护进程</td></tr><tr><td style="text-align:center;">8</td><td><code>ProcessProtect.exe</code></td><td>进程保护</td></tr><tr><td style="text-align:center;">9</td><td><code>RunClient.exe</code></td><td>运行客户端</td></tr></tbody></table><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to “批量操作”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>功能</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>10</strong></td><td><strong>终止所有学生端进程</strong></td><td>一键终止全部 16+ 个相关进程</td></tr><tr><td style="text-align:center;"><strong>11</strong></td><td><strong>持续监控模式</strong></td><td>循环监控并自动终止关键进程</td></tr><tr><td style="text-align:center;"><strong>12</strong></td><td>返回主菜单</td><td>-</td></tr></tbody></table><h2 id="持续监控模式详解-⭐" tabindex="-1">持续监控模式详解 ⭐ <a class="header-anchor" href="#持续监控模式详解-⭐" aria-label="Permalink to “持续监控模式详解 ⭐”">​</a></h2><p>这是<strong>防止学生端自动重启反弹的杀手锏功能</strong>。</p><h3 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to “工作原理”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>初始化 → 显示当前时间 → 强制终止 Student.exe</span></span>
<span class="line"><span>    ↓                        ↓</span></span>
<span class="line"><span> 返回顶部 ← 等待2秒 ← 强制终止 ScreenRender.exe</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>                   强制终止 MultiClient.exe</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>                   强制终止 DeviceControl_x64.exe</span></span></code></pre></div><p>以 <strong>2 秒为间隔</strong>，无限循环终止以下 4 个关键进程：</p><ul><li><code>Student.exe</code></li><li><code>MultiClient.exe</code></li><li><code>ScreenRender.exe</code></li><li><code>DeviceControl_x64.exe</code></li></ul><h3 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h3><ul><li>⭐ <strong>一键解锁后学生端不断重启</strong> → 开启持续监控</li><li>⭐ <strong>上课全程保持自由状态</strong> → 进入持续监控模式</li><li>⭐ <strong>需要长时间不受控制</strong> → 持续监控直到下课</li></ul><h3 id="退出方式" tabindex="-1">退出方式 <a class="header-anchor" href="#退出方式" aria-label="Permalink to “退出方式”">​</a></h3><p>在 CMD 窗口中按 <strong><code>Ctrl + C</code></strong> 可以退出循环，返回主菜单。</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">提示</p><p>持续监控模式会持续占用一个 CMD 窗口。建议在需要长时间自由操作时使用，且可以最小化窗口让它后台运行。</p><p>该模式每 2 秒执行一次终止操作，对系统性能影响极小。</p></div><h2 id="执行方式" tabindex="-1">执行方式 <a class="header-anchor" href="#执行方式" aria-label="Permalink to “执行方式”">​</a></h2><p>选择具体进程后，会有 <strong>5 秒倒计时</strong>，你可以按任意键立即执行。</p>`,21)])])}const x=e(r,[["render",s]]);export{g as __pageData,x as default};
